# area: inheritance_mro
# hypothesis: in a diamond MRO, super() visits each base once in linearised order, so checkers and CPython should agree on the list that Bottom().trace() builds.
from typing import reveal_type


class Root:
    def trace(self) -> list[str]:
        return ['Root']


class Left(Root):
    def trace(self) -> list[str]:
        return ['Left', *super().trace()]


class Right(Root):
    def trace(self) -> list[str]:
        return ['Right', *super().trace()]


class Bottom(Left, Right):
    def trace(self) -> list[str]:
        return ['Bottom', *super().trace()]


class Narrow(Root):
    def trace(self) -> list[str]:
        return ['Narrow']


class Mixed(Bottom, Narrow):
    tag: str = 'mixed'


class Broken(Root):
    def trace(self) -> str:  # expect-error: return type str is not list[str]
        return 'broken'


reveal_type(Bottom().trace())
reveal_type(Mixed().trace())
reveal_type(Narrow().trace())
Broken().trace()
